        static_assert(std::is_same_v<decltype(m::B2_SPECULATIVE_DISTANCE()), decltype(raw_B2_SPECULATIVE_DISTANCE)>);
        EXPECT_EQ(m::B2_SPECULATIVE_DISTANCE(), raw_B2_SPECULATIVE_DISTANCE) << "B2_SPECULATIVE_DISTANCE";
#pragma pop_macro("B2_SPECULATIVE_DISTANCE")
        auto raw_B2_CONTACT_RECYCLE_DISTANCE = B2_CONTACT_RECYCLE_DISTANCE;
#pragma push_macro("B2_CONTACT_RECYCLE_DISTANCE")
