        EXPECT_EQ(m::B2_CONTACT_RECYCLE_DISTANCE(), raw_B2_CONTACT_RECYCLE_DISTANCE) << "B2_CONTACT_RECYCLE_DISTANCE";
#pragma pop_macro("B2_CONTACT_RECYCLE_DISTANCE")
