TEST(MacroFunctions, B2_IS_NULL) {
    unary([](auto id) {
        static_assert(std::is_same_v<decltype(B2_IS_NULL(id)), decltype((m::B2_IS_NULL)(id))>);
        EXPECT_EQ(B2_IS_NULL(id), (m::B2_IS_NULL)(id));
    });
}
TEST(MacroFunctions, B2_IS_NON_NULL) {
    unary([](auto id) {
        static_assert(std::is_same_v<decltype(B2_IS_NON_NULL(id)), decltype((m::B2_IS_NON_NULL)(id))>);
        EXPECT_EQ(B2_IS_NON_NULL(id), (m::B2_IS_NON_NULL)(id));
    });
}
TEST(MacroFunctions, B2_ID_EQUALS) {
    binary([](auto id1, auto id2) {
        static_assert(std::is_same_v<decltype(B2_ID_EQUALS(id1, id2)), decltype((m::B2_ID_EQUALS)(id1, id2))>);
        EXPECT_EQ(B2_ID_EQUALS(id1, id2), (m::B2_ID_EQUALS)(id1, id2));
    });
}
